```python
"""
Python Decorators: A Comprehensive Tutorial
===========================================

A decorator is a design pattern in Python that allows you to modify or enhance
the behavior of functions or classes without permanently modifying them.
"""

# ============================================================================
# 1. BASIC DECORATOR SYNTAX
# ============================================================================

print("=" * 70)
print("1. BASIC DECORATOR SYNTAX")
print("=" * 70)

# Simple decorator that wraps a function
def simple_decorator(func):
    """A basic decorator that wraps a function."""
    def wrapper():
        print("Something is happening before the function is called.")
        func()
        print("Something is happening after the function is called.")
    return wrapper

# Using the decorator with @ syntax
@simple_decorator
def say_hello():
    print("Hello!")

say_hello()
print()

# The above is equivalent to:
def say_goodbye():
    print("Goodbye!")

say_goodbye = simple_decorator(say_goodbye)
say_goodbye()
print()


# Decorator that preserves function arguments
def decorator_with_args(func):
    """Decorator that handles functions with arguments."""
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with args={args}, kwargs={kwargs}")
        result = func(*args, **kwargs)
        print(f"Function {func.__name__} returned: {result}")
        return result
    return wrapper

@decorator_with_args
def add(a, b):
    return a + b

result = add(5, 3)
print(f"Final result: {result}\n")


# Using functools.wraps to preserve function metadata
from functools import wraps

def better_decorator(func):
    """Decorator that preserves the original function's metadata."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f"Executing {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

@better_decorator
def greet(name):
    """Greet someone by name."""
    return f"Hello, {name}!"

print(greet("Alice"))
print(f"Function name: {greet.__name__}")
print(f"Function docstring: {greet.__doc__}\n")


# ============================================================================
# 2. DECORATORS WITH ARGUMENTS
# ============================================================================

print("=" * 70)
print("2. DECORATORS WITH ARGUMENTS")
print("=" * 70)

# Decorator factory that accepts arguments
def repeat(times):
    """Decorator that repeats function execution."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            results = []
            for _ in range(times):
                result = func(*args, **kwargs)
                results.append(result)
            return results
        return wrapper
    return decorator

@repeat(times=3)
def say_hi():
    print("Hi!")
    return "Hi"

results = say_hi()
print(f"Results: {results}\n")


# Decorator with optional arguments
def smart_divide(default_value=None):
    """Decorator that handles division by zero."""
    def decorator(func):
        @wraps(func)
        def wrapper(a, b):
            if b == 0:
                print(f"Warning: Division by zero! Returning {default_value}")
                return default_value
            return func(a, b)
        return wrapper
    return decorator

@smart_divide(default_value=0)
def divide(a, b):
    return a / b

print(f"10 / 2 = {divide(10, 2)}")
print(f"10 / 0 = {divide(10, 0)}\n")


# Timer decorator with configurable output
def timer(unit="seconds"):
    """Decorator that measures execution time."""
    import time

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            start = time.time()
            result = func(*args, **kwargs)
            end = time.time()

            elapsed = end - start
            if unit == "milliseconds":
                elapsed *= 1000
                unit_str = "ms"
            else:
                unit_str = "s"

            print(f"{func.__name__} took {elapsed:.4f} {unit_str}")
            return result
        return wrapper
    return decorator

@timer(unit="milliseconds")
def slow_function():
    import time
    time.sleep(0.1)
    return "Done"

slow_function()
print()


# ============================================================================
# 3. CLASS DECORATORS
# ============================================================================

print("=" * 70)
print("3. CLASS DECORATORS")
print("=" * 70)

# Decorator as a class
class CountCalls:
    """Decorator class that counts function calls."""

    def __init__(self, func):
        self.func = func
        self.count = 0
        wraps(func)(self)  # Preserve function metadata

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"Call {self.count} to {self.func.__name__}")
        return self.func(*args, **kwargs)

@CountCalls
def process_data(data):
    return f"Processing: {data}"

process_data("item1")
process_data("item2")
process_data("item3")
print()


# Class decorator (decorating a class)
def add_repr(cls):
    """Decorator that adds a __repr__ method to a class."""
    def __repr__(self):
        attrs = ', '.join(f"{k}={v!r}" for k, v in self.__dict__.items())
        return f"{cls.__name__}({attrs})"

    cls.__repr__ = __repr__
    return cls

@add_repr
class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

person = Person("Bob", 30)
print(person)
print()


# Singleton pattern using class decorator
def singleton(cls):
    """Decorator that makes a class a singleton."""
    instances = {}

    @wraps(cls)
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]

    return get_instance

@singleton
class Database:
    def __init__(self):
        print("Initializing database connection...")
        self.connection = "Connected"

db1 = Database()
db2 = Database()
print(f"db1 is db2: {db1 is db2}")
print()


# ============================================================================
# 4. BUILT-IN DECORATORS
# ============================================================================

print("=" * 70)
print("4. BUILT-IN DECORATORS")
print("=" * 70)

# @property decorator
class Temperature:
    """Class demonstrating @property decorator."""

    def __init__(self, celsius):
        self._celsius = celsius

    @property
    def celsius(self):
        """Get temperature in Celsius."""
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        """Set temperature in Celsius."""
        if value < -273.15:
            raise ValueError("Temperature below absolute zero!")
        self._celsius = value

    @property
    def fahrenheit(self):
        """Get temperature in Fahrenheit."""
        return (self._celsius * 9/5) + 32

    @fahrenheit.setter
    def fahrenheit(self, value):
        """Set temperature in Fahrenheit."""
        self.celsius = (value - 32) * 5/9

temp = Temperature(25)
print(f"Temperature: {temp.celsius}°C = {temp.fahrenheit}°F")
temp.fahrenheit = 100
print(f"After setting to 100°F: {temp.celsius}°C = {temp.fahrenheit}°F")
print()


# @staticmethod and @classmethod
class MathOperations:
    """Class demonstrating @staticmethod and @classmethod."""

    pi = 3.14159

    @staticmethod
    def add(a, b):
        """Static method doesn't need class or instance."""
        return a + b

    @classmethod
    def circle_area(cls, radius):
        """Class method receives the class as first argument."""
        return cls.pi * radius ** 2

    @classmethod
    def from_diameter(cls, diameter):
        """Alternative constructor using class method."""
        radius = diameter / 2
        return cls.circle_area(radius)

print(f"5 + 3 = {MathOperations.add(5, 3)}")
print(f"Circle area (r=5): {MathOperations.circle_area(5):.2f}")
print(f"Circle area (d=10): {MathOperations.from_diameter(10):.2f}")
print()


# @abstractmethod from abc module
from abc import ABC, abstractmethod

class Animal(ABC):
    """Abstract base class for animals."""

    @abstractmethod
    def make_sound(self):
        """Abstract method that must be implemented by subclasses."""
        pass

    def describe(self):
        """Concrete method available to all subclasses."""
        return f"I am a {self.__class__.__name__}"

class Dog(Animal):
    def make_sound(self):
        return "Woof!"

class Cat(Animal):
    def make_sound(self):
        return "Meow!"

dog = Dog()
cat = Cat()
print(f"{dog.describe()} and I say {dog.make_sound()}")
print(f"{cat.describe()} and I say {cat.make_sound()}")
print()

# Attempting to instantiate abstract class would raise TypeError:
# animal = Animal()  # TypeError: Can't instantiate abstract class


# ============================================================================
# 5. PRACTICAL EXAMPLES
# ============================================================================

print("=" * 70)
print("5. PRACTICAL EXAMPLES")
print("=" * 70)

# Example 1: Caching/Memoization
def memoize(func):
    """Cache function results for given arguments."""
    cache = {}

    @wraps(func)
    def wrapper(*args):
        if args not in cache:
            print(f"Computing {func.__name__}{args}...")
            cache[args] = func(*args)
        else:
            print(f"Using cached result for {func.__name__}{args}")
        return cache[args]

    return wrapper

@memoize
def fibonacci(n):
    """Calculate Fibonacci number (inefficient without memoization)."""
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(f"fibonacci(10) = {fibonacci(10)}")
print(f"fibonacci(10) again = {fibonacci(10)}")
print()


# Example 2: Authentication/Authorization
def require_auth(role=None):
    """Decorator to check user authentication and authorization."""
    def decorator(func):
        @wraps(func)
        def wrapper(user, *args, **kwargs):
            if not user.get("authenticated"):
                raise PermissionError(f"User must be authenticated to call {func.__name__}")

            if role and user.get("role") != role:
                raise PermissionError(f"User must have role '{role}' to call {func.__name__}")

            return func(user, *args, **kwargs)
        return wrapper
    return decorator

@require_auth(role="admin")
def delete_user(user, user_id):
    return f"User {user_id} deleted by {user['name']}"

@require_auth()
def view_profile(user):
    return f"Viewing profile for {user['name']}"

admin_user = {"name": "Admin", "authenticated": True, "role": "admin"}
regular_user = {"name": "John", "authenticated": True, "role": "user"}

print(view_profile(regular_user))
print(delete_user(admin_user, "user123"))

try:
    delete_user(regular_user, "user123")
except PermissionError as e:
    print(f"Error: {e}")
print()


# Example 3: Retry logic
def retry(max_attempts=3, delay=1, exceptions=(Exception,)):
    """Retry a function if it raises specified exceptions."""
    import time

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    attempts += 1
                    if attempts >= max_attempts:
                        print(f"Failed after {max_attempts} attempts")
                        raise
                    print(f"Attempt {attempts} failed: {e}. Retrying in {delay}s...")
                    time.sleep(delay)
        return wrapper
    return decorator

# Simulated unreliable function
import random

@retry(max_attempts=5, delay=0.5, exceptions=(ConnectionError,))
def unreliable_api_call():
    """Simulates an unreliable API call."""
    if random.random() < 0.7:  # 70% failure rate
        raise ConnectionError("Connection failed")
    return "Success!"

try:
    result = unreliable_api_call()
    print(f"API call result: {result}")
except ConnectionError:
    print("API call failed after all retries")
print()


# Example 4: Logging decorator
def log_calls(log_file=None):
    """Decorator that logs function calls with arguments and results."""
    import datetime

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            timestamp = datetime.datetime.now().isoformat()
            args_repr = [repr(a) for a in args]
            kwargs_repr = [f"{k}={v!r}" for k, v in kwargs.items()]
            signature = ", ".join(args_repr + kwargs_repr)

            log_message = f"[{timestamp}] Calling {func.__name__}({signature})"

            try:
                result = func(*args, **kwargs)
                log_message += f" -> {result!r}"
                return result
            except Exception as e:
                log_message += f" -> raised {type(e).__name__}: {e}"
                raise
            finally:
                if log_file:
                    with open(log_file, 'a') as f:
                        f.write(log_message + '\n')
                else:
                    print(log_message)

        return wrapper
    return decorator

@log_calls()
def calculate_total(items, tax_rate=0.1):
    """Calculate total price with tax."""
    subtotal = sum(items)
    total = subtotal * (1 + tax_rate)
    return round(total, 2)

calculate_total([10, 20, 30], tax_rate=0.15)
print()


# Example 5: Validation decorator
def validate_types(**type_checks):
    """Decorator that validates argument types."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Get function signature
            import inspect
            sig = inspect.signature(func)
            bound_args = sig.bind(*args, **kwargs)
            bound_args.apply_defaults()

            # Check types
            for param_name, expected_type in type_checks.items():
                if param_name in bound_args.arguments:
                    value = bound_args.arguments[param_name]
                    if not isinstance(value, expected_type):
                        raise TypeError(
                            f"Argument '{param_name}' must be {expected_type.__name__}, "
                            f"got {type(value).__name__}"
                        )

            return func(*args, **kwargs)
        return wrapper
    return decorator

@validate_types(name=str, age=int, salary=float)
def create_employee(name, age, salary):
    """Create an employee record."""
    return {"name": name, "age": age, "salary": salary}

employee = create_employee("Alice", 30, 75000.0)
print(f"Created employee: {employee}")

try:
    create_employee("Bob", "thirty", 60000.0)  # Wrong type for age
except TypeError as e:
    print(f"Validation error: {e}")
print()


# Example 6: Deprecation warning
import warnings

def deprecated(reason):
    """Decorator to mark functions as deprecated."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                f"{func.__name__} is deprecated. {reason}",
                category=DeprecationWarning,
                stacklevel=2
            )
            return func(*args, **kwargs)
        return wrapper
    return decorator

@deprecated("Use new_function() instead")
def old_function(x):
    """This function is deprecated."""
    return x * 2

result = old_function(5)
print(f"Result: {result}")
print()


# Stacking multiple decorators
print("=" * 70)
print("BONUS: STACKING DECORATORS")
print("=" * 70)

@timer(unit="milliseconds")
@memoize
@log_calls()
def complex_calculation(n):
    """Function with multiple decorators stacked."""
    import time
    time.sleep(0.01)  # Simulate work
    return sum(range(n))

print("First call:")
result1 = complex_calculation(1000)
print(f"Result: {result1}\n")

print("Second call (should use cache):")
result2 = complex_calculation(1000)
print(f"Result: {result2}\n")

print("=" * 70)
print("TUTORIAL COMPLETE")
print("=" * 70)
```

This comprehensive tutorial covers all the key aspects of Python decorators with practical, runnable examples. Each section builds on the previous one, starting from basic concepts and progressing to advanced real-world use cases.

**Key takeaways:**

1. **Basic decorators** wrap functions to add behavior before/after execution
2. **Decorators with arguments** require an extra level of nesting (decorator factory)
3. **Class decorators** can be implemented as classes with `__call__` or as functions that modify classes
4. **Built-in decorators** like `@property`, `@staticmethod`, `@classmethod`, and `@abstractmethod` solve common patterns
5. **Practical applications** include caching, authentication, retry logic, logging, validation, and deprecation warnings

The code is fully executable and demonstrates each concept with clear examples. You can run this file directly to see all the examples in action!
